contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool newClosed) public {
        IProduct.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = PayoffDefinition({
            payoffType: PayoffDefinitionLib.PayoffType(uint8(0)),
            payoffDirection: PayoffDefinitionLib.PayoffDirection(uint8(0)),
            data: bytes30(0)
        });
        info.oracle = IOracleProvider(address(this));
        info.maintenance = UFixed18Lib.ZERO;
        info.fundingFee = UFixed18Lib.ZERO;
        info.makerFee = UFixed18Lib.ZERO;
        info.takerFee = UFixed18Lib.ZERO;
        info.positionFee = UFixed18Lib.ZERO;
        info.makerLimit = UFixed18Lib.MAX;
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(int128(0)),
            maxRate: PackedFixed18.wrap(int128(0)),
            targetRate: PackedFixed18.wrap(int128(0)),
            targetUtilization: PackedUFixed18.wrap(uint128(0))
        });

        c.initialize(info);
        c.updateClosed(newClosed);

        assert(c.closed() == newClosed);
    }

    fallback(bytes calldata) external payable returns (bytes memory) {
        bytes4 sel = msg.sig;
        if (sel == bytes4(keccak256("paused()"))) {
            return abi.encode(false);
        }
        if (sel == bytes4(keccak256("minFundingFee()"))) {
            return abi.encode(uint256(0));
        }
        if (sel == bytes4(keccak256("owner(uint256)"))) {
            return abi.encode(address(this));
        }
        if (sel == bytes4(keccak256("coordinatorFor(address)"))) {
            return abi.encode(uint256(1));
        }
        if (
            sel == bytes4(keccak256("incentivizer()")) ||
            sel == bytes4(keccak256("collateral()")) ||
            sel == bytes4(keccak256("oracle()"))
        ) {
            return abi.encode(address(this));
        }
        if (sel == bytes4(keccak256("sync()"))) {
            return abi.encode(uint256(7), uint256(1), int256(1e18));
        }
        return "";
    }

    receive() external payable {}
}

